CREATE POLICY "Public reads service videos" ON storage.objects FOR SELECT TO anon, authenticated USING (bucket_id = 'service-videos');
CREATE POLICY "Admins upload service videos" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'service-videos' AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins update service videos" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'service-videos' AND public.has_role(auth.uid(), 'admin')) WITH CHECK (bucket_id = 'service-videos' AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins delete service videos" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'service-videos' AND public.has_role(auth.uid(), 'admin'));